import{_ as e,c as r,o as a,a7 as d}from"./chunks/framework.DLVsJyUe.js";const x=JSON.parse('{"title":"角色与权限","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/roles.md","filePath":"orbitcontrol/user-guide/roles.md"}'),n={name:"orbitcontrol/user-guide/roles.md"};function l(s,t,o,i,c,h){return a(),r("div",null,t[0]||(t[0]=[d('<h1 id="角色与权限" tabindex="-1">角色与权限 <a class="header-anchor" href="#角色与权限" aria-label="Permalink to &quot;角色与权限&quot;">​</a></h1><p>平台权限以<strong>企业</strong>为单位管理。每个用户在企业中拥有一个角色，角色决定了可使用的功能。</p><h2 id="企业角色" tabindex="-1">企业角色 <a class="header-anchor" href="#企业角色" aria-label="Permalink to &quot;企业角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>说明</th><th>如何获得</th></tr></thead><tbody><tr><td><strong>所有者</strong></td><td>企业的一切权限，包括企业设置、成员管理、转让企业</td><td>创建企业的用户自动成为所有者，每个企业有且仅有一个所有者</td></tr><tr><td><strong>管理员</strong></td><td>企业内的管理与运维权限，可管理成员和各项资源</td><td>通过<a href="./tenant.html">所有权转让</a>或开放 API 调整（界面直接调整角色的入口建设中）</td></tr><tr><td><strong>成员</strong></td><td>日常操作权限，可操控设备、编排任务、查看数据</td><td>通过邀请码加入企业后默认为成员</td></tr></tbody></table><h2 id="权限一览" tabindex="-1">权限一览 <a class="header-anchor" href="#权限一览" aria-label="Permalink to &quot;权限一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th style="text-align:center;">成员</th><th style="text-align:center;">管理员</th><th style="text-align:center;">所有者</th></tr></thead><tbody><tr><td>实况（设备控制、视频墙）</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>任务规划（任务、计划、流程、标注、路网）</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>数据中心（语音库、日志、画廊、回放）</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>管理（站点、设备、地图、用户、应用）</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>企业管理（成员与角色、邀请、入驻审批）</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>企业信息设置、转让企业、移除成员</td><td style="text-align:center;">❌</td><td style="text-align:center;">部分</td><td style="text-align:center;">✅</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>权限由服务端强制校验。即使通过 URL 直接访问管理页面，无权限的操作也会被拒绝。</p></div><h2 id="站点操作人员" tabindex="-1">站点操作人员 <a class="header-anchor" href="#站点操作人员" aria-label="Permalink to &quot;站点操作人员&quot;">​</a></h2><p>除了企业级角色，站点还可以单独分配<strong>操作人员</strong>：只有被分配到站点的用户，才能操作该站点下的设备。在 <a href="./sites.html">站点管理</a> 中编辑站点时设置。</p><h2 id="账号状态" tabindex="-1">账号状态 <a class="header-anchor" href="#账号状态" aria-label="Permalink to &quot;账号状态&quot;">​</a></h2><p>管理员可以在 <a href="./users.html">用户管理</a> 中禁用或启用用户账号，被禁用的账号无法登录。当前登录账号不可自我禁用。</p>',11)]))}const b=e(n,[["render",l]]);export{x as __pageData,b as default};
